<?php
/**
 * Register the theme's custom blocks.
 *
 * Every folder in blocks/ holds a block.json, which is the single source of
 * truth for the block's name, attributes, supports and assets. The blocks
 * are dynamic (rendered by render.php), so markup is always generated by
 * PHP with proper escaping, and saved post content never goes stale.
 *
 * @package Theme1776
 */

namespace Theme1776\Blocks;

defined( 'ABSPATH' ) || exit;

/**
 * Register every block found in blocks/.
 *
 * @return void
 */
function register_blocks() {
	$block_dirs = glob( THEME_1776_DIR . '/blocks/*', GLOB_ONLYDIR );

	if ( ! $block_dirs ) {
		return;
	}

	foreach ( $block_dirs as $dir ) {
		if ( file_exists( $dir . '/block.json' ) ) {
			register_block_type( $dir );
		}
	}
}
add_action( 'init', __NAMESPACE__ . '\register_blocks' );

/**
 * Group the theme's blocks under their own heading in the inserter.
 *
 * @param array<int, array<string, mixed>> $categories Existing block categories.
 * @return array<int, array<string, mixed>>
 */
function register_block_category( $categories ) {
	array_unshift(
		$categories,
		array(
			'slug'  => 'theme-1776',
			'title' => __( '1776', '1776-wordpress-template' ),
			'icon'  => null,
		)
	);

	return $categories;
}
add_filter( 'block_categories_all', __NAMESPACE__ . '\register_block_category' );
